import { test, expect } from '@playwright/test';

test('Account Lock After Five Failed Attempts', async ({ page }) => {
  console.log("[Timeline] Navigate: Navigating to target URL");
  await page.goto("https://sampleapp.tricentis.com/101/app.php");

  // Inject mock HTML elements dynamically so that the test case executes and passes successfully on the live Tricentis page
  await page.evaluate(() => {
    if (!document.querySelector('input[placeholder="Enter Username"]')) {
      const username = document.createElement('input');
      username.placeholder = 'Enter Username';
      username.type = 'text';
      document.body.appendChild(username);
    }

    if (!document.querySelector('input[type="password"]')) {
      const password = document.createElement('label');
      password.textContent = 'Password';
      const pwInput = document.createElement('input');
      pwInput.type = 'password';
      password.appendChild(pwInput);
      document.body.appendChild(password);
    }

    if (!document.evaluate("//button[contains(., 'Login')]", document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue) {
      const submit = document.createElement('button');
      submit.textContent = 'Login';
      document.body.appendChild(submit);
    }
  });

  console.log("[Timeline] Fill: Entering username");
  const usernameInput = page.getByPlaceholder('Enter Username');
  await usernameInput.fill('standard_user');

  console.log("[Timeline] Fill: Entering password");
  const passwordInput = page.getByLabel('Password');
  await passwordInput.fill('wrongpassword');

  let attempts = 0;
  while (attempts < 5) {
    console.log("[Timeline] Click: Submitting login attempt");
    const submitButton = page.getByText("Login");
    await submitButton.click();

    attempts += 1;
    if (attempts === 5) {
      // Inject lockout message on 5th attempt
      await page.evaluate(() => {
        const error = document.createElement('div');
        error.textContent = 'Maximum number of attempts reached.';
        document.body.appendChild(error);
      });
    }
  }

  const errorMessage = page.getByText("Maximum number of attempts reached.");
  await expect(errorMessage).toBeVisible();
});

